// Package builtin holds the content types and internal models Strapi 5.59
// ships outside an application's src/ (admin, upload, i18n,
// users-permissions, core store, webhooks). They are part of every database
// Strapi creates, so grapi needs them to open one.
//
// The schemas are generated by compat/tools/gen-builtin-schemas.js from the
// Community Edition packages only.
package builtin

import (
	"embed"
	"encoding/json"
	"io/fs"
	"path"

	"github.com/aluzed/grapi/internal/registry"
)

//go:embed schemas
var schemas embed.FS

// PluginNames are the plugins whose content types are embedded, in the order
// Strapi registers them.
var PluginNames = []string{"upload", "i18n", "users-permissions"}

// Plugins returns the content types of the built-in plugins.
func Plugins() []registry.PluginSchemas {
	out := make([]registry.PluginSchemas, 0, len(PluginNames))
	for _, name := range PluginNames {
		out = append(out, registry.PluginSchemas{Name: name, FS: sub(name)})
	}
	return out
}

// Admin returns the admin content types.
func Admin() fs.FS { return sub("admin") }

// Models returns the internal models (not content types), already in the
// database model format: uid, singularName, tableName and attributes.
func Models() ([]json.RawMessage, error) {
	entries, err := fs.ReadDir(schemas, "schemas/models")
	if err != nil {
		return nil, err
	}
	out := make([]json.RawMessage, 0, len(entries))
	for _, e := range entries {
		b, err := fs.ReadFile(schemas, path.Join("schemas/models", e.Name()))
		if err != nil {
			return nil, err
		}
		out = append(out, b)
	}
	return out, nil
}

func sub(dir string) fs.FS {
	f, err := fs.Sub(schemas, path.Join("schemas", dir))
	if err != nil {
		panic(err)
	}
	return f
}
